Translate("ptBR", "helendis-riverhorn", {
	title = "Helendis Riverhorn",
	subtitle = "Batedor da Vigia de Morgan",
	found = [=[A borda leste da Vigia de Morgan, acima das encostas dos dracônicos]=],
	hint = [=[Fale com o elfo noturno que vigia os dracônicos da borda da Vigia de Morgan.]=],
	allegiance = "Aliança · Vigia de Morgan",
	aliases = { "Helendis" },
	sections = {
		{
			title = "Resumo",
			text = [=[Helendis Riverhorn é um {link:night-elves}elfo noturno{/link} que serve na {link:morgan-s-vigil}Vigia de Morgan{/link}. Ele fica na borda da crista, acima das encostas onde os dracônicos negros se reúnem, e os observa. Invoca {link:cenarius}Cenarius{/link} quando deseja o bem a um soldado. Foi ele quem primeiro viu com clareza o que os {link:blackrock-clan}orcs Rocha Negra{/link} realmente eram, e quem enviou esse conhecimento ao sul, a {link:lakeshire}Vila Plácida{/link}.]=],
		},
		{
			title = "Importância",
			text = [=[Helendis deu início à cadeia de acontecimentos que um dia chegaria à sala do trono de {link:stormwind-city}Ventobravo{/link}. Os humanos sempre acreditaram que os {link:blackrock-mountain}Rocha Negra{/link} eram selvagens por natureza. Helendis descobriu que eles eram impelidos. A fúria que os enche, escreveu ele, é alimentada pela revoada negra, e são os dragões os seus verdadeiros senhores.]=],
		},
		{
			title = "Feitos",
			text = [=[• Combate os dracônicos que pressionam {link:morgan-s-vigil}a Vigia{/link}.
