		{ id = "katrana-prestor", name = "Katrana Prestor", note = "ouviu seu aviso de segunda mão" },
	},
})

Translate("ptBR", "ragged-john", {
	title = "Ragged John",
	subtitle = "Testemunha da Montanha",
	found = "Monte Candente, sob a crista norte",
	hint = [=[Encontre o anão bêbado que se esconde numa caverna no Monte Candente.]=],
	allegiance = "Nenhuma",
	sections = {
		{
			title = "Resumo",
			text = [=[Ragged John é um {link:dwarves}anão{/link} que vive no {link:flame-crest}Monte Candente{/link}, na caverna sob a crista norte, e raramente está sóbrio. Ele estava ao lado do Marechal Windsor no dia em que o marechal desapareceu. O {link:marshal-maxwell}Marechal Maxwell{/link} o chama de covarde. John prefere dizer que é um pouco desleixado, e que anões nunca ficam bêbados.]=],
		},
		{
			title = "Importância",
			text = [=[John é a única testemunha do destino de Windsor. Sua história, por mais difícil de acompanhar que seja, revelou à {link:morgan-s-vigil}Vigia de Morgan{/link} que Windsor ainda vivia, e onde procurá-lo.]=],
		},
		{
			title = "Feitos",
			text = [=[• Marchou com o Marechal Windsor para dentro da {link:blackrock-mountain}Montanha Rocha Negra{/link}.
• Escondeu-se nas sombras quando os orcs atacaram.
• Entra de vez em quando no Pico da Rocha Negra e escuta o que os orcs dizem.]=],
		},
	},
	chapters = {
		{
			title = "A História de Ragged John",
			hint = "Ouça de Ragged John o que aconteceu ao Marechal Windsor.",
			text = [=[John conta tudo em detalhes. Windsor estava de humor sombrio naquele dia e repetia que algo parecia errado. No coração da montanha, os {link:blackrock-mountain}Rocha Negra{/link} caíram sobre eles, e John se escondeu. Windsor se manteve firme com Ironfoe, o martelo matador de orcs que {link:franclorn-forgewright}Franclorn Forgewright{/link} fez para um de seus antepassados, e ainda estava de pé, encharcado de sangue de {link:orcs}orc{/link}, quando a luta parou. Então vieram os {link:dark-iron-dwarves}Ferro Negro{/link}, às centenas. Não o mataram, talvez porque seu antepassado fora amigo do povo deles. Levaram-no prisioneiro, e seu líder levou Ironfoe. John nunca mais o viu.]=],
		},
		{
			title = "Leite Materno",
			hint = [=[Traga a Ragged John uma amostra viva do veneno mais mortal do Pico.]=],
			text = [=[No Pico, John ouviu os orcs falarem de um veneno que chamam de Leite Materno, por causa da grande aranha Mãe Fumateia. Ele o queria, e não de uma glândula: tinha de vir fresco, nas veias de alguém que ela tivesse picado. Quando o extraiu, explicou que faria com ele sua melhor cerveja até então.]=],
		},
	},
	mentions = {
		{ text = "Os Verdadeiros Senhores" },
		{ text = "Leite Materno" },
	},
	bonds = {
		{ id = "reginald-windsor", name = "Reginald Windsor", note = "o marechal com quem marchou" },
		{ id = "marshal-maxwell", name = "Marechal Maxwell", note = "o chama de covarde" },
		{ id = "franclorn-forgewright", name = "Franclorn Forgewright", note = "fez o martelo de Windsor" },
	},
})

